package module

import("fmt";"strings";"unicode")
type Manifest struct{Name string `json:"name"`;Version string `json:"version"`;Capabilities []string `json:"capabilities"`;Dependencies []string `json:"dependencies,omitempty"`}
func clean(v string)string{return strings.TrimSpace(v)}
func hasControl(v string)bool{for _,r:=range v{if unicode.IsControl(r){return true}};return false}
func(m Manifest)Validate()error{name:=clean(m.Name);version:=clean(m.Version);if name==""{return fmt.Errorf("module name is required")};if version==""{return fmt.Errorf("module version is required")};if len(name)>256||len(version)>128||hasControl(name)||hasControl(version){return fmt.Errorf("module identity is invalid")};seen:=map[string]struct{}{};for _,raw:=range m.Capabilities{c:=clean(raw);if c==""{return fmt.Errorf("module %q contains an empty capability",name)};if len(c)>256||hasControl(c){return fmt.Errorf("module %q capability is invalid",name)};if _,ok:=seen[c];ok{return fmt.Errorf("module %q declares duplicate capability %q",name,c)};seen[c]=struct{}{}};seen=map[string]struct{}{};for _,raw:=range m.Dependencies{d:=clean(raw);if d==""{return fmt.Errorf("module %q contains an empty dependency",name)};if len(d)>256||hasControl(d){return fmt.Errorf("module %q dependency is invalid",name)};if d==name{return fmt.Errorf("module %q cannot depend on itself",name)};if _,ok:=seen[d];ok{return fmt.Errorf("module %q declares duplicate dependency %q",name,d)};seen[d]=struct{}{}};if len(m.Capabilities)>256||len(m.Dependencies)>256{return fmt.Errorf("module dependency or capability list is too large")};return nil}
func(m Manifest)Normalize()Manifest{m.Name=clean(m.Name);m.Version=clean(m.Version);dedupe:=func(in []string)[]string{seen:=map[string]struct{}{};out:=make([]string,0,len(in));for _,v:=range in{v=clean(v);if v==""{continue};if _,ok:=seen[v];ok{continue};seen[v]=struct{}{};out=append(out,v)};return out};m.Capabilities=dedupe(m.Capabilities);m.Dependencies=dedupe(m.Dependencies);return m}
